315	
316				*q  = (frame[0] & X25_Q_BIT) == X25_Q_BIT;
317				*d  = (frame[0] & X25_D_BIT) == X25_D_BIT;
318				*m  = (frame[3] & X25_EXT_M_BIT) == X25_EXT_M_BIT;
319				*nr = (frame[3] >> 1) & 0x7F;
320				*ns = (frame[2] >> 1) & 0x7F;
