322			}
323		} else {
324			if ((frame[2] & 0x01) == X25_DATA) {
325				*q  = (frame[0] & X25_Q_BIT) == X25_Q_BIT;
326				*d  = (frame[0] & X25_D_BIT) == X25_D_BIT;
327				*m  = (frame[2] & X25_STD_M_BIT) == X25_STD_M_BIT;
328				*nr = (frame[2] >> 5) & 0x07;
329				*ns = (frame[2] >> 1) & 0x07;
